mapper.select:
SELECT b.id, b.factory_id, b.cutting_plan_id, b.order_id, o.order_no, o.style_id, s.style_code, s.style_name, b.color, b.size, b.fabric, b.part, cp.bed_no, cp.barcode, b.bundle_no, b.global_bundle_no, b.qty, b.cutting_pieces, (SELECT COUNT(DISTINCT op.process_id) FROM order_process op WHERE op.order_id = b.order_id) AS total_processes, (SELECT COUNT(DISTINCT wr.process_id) FROM work_report wr WHERE wr.status = 1 AND wr.bundle_id IN ( SELECT b2.id FROM bundle b2 WHERE b2.bundle_no = b.bundle_no AND b2.order_id = b.order_id )) AS completed_processes, b.created_at FROM bundle b LEFT JOIN `order` o ON b.order_id = o.id AND o.deleted = 0 LEFT JOIN style s ON o.style_id = s.id AND s.deleted = 0 LEFT JOIN cutting_plan cp ON b.cutting_plan_id = cp.id AND cp.deleted = 0 WHERE b.factory_id = #{factoryId}
AND b.bundle_no LIKE CONCAT('%', #{bundleNo}, '%')
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND s.style_code LIKE CONCAT('%', #{styleCode}, '%')
AND b.color = #{color}
AND b.size = #{size}
ORDER BY b.created_at DESC
